/bin/bash -lc "cd /workspace && python3 - <<'PY'
from collections import Counter,defaultdict
cnt=Counter(); examples=defaultdict(list)
for line in open('sei_cistrome_mapping.tsv'):
    if line.startswith('cistrome_id'): continue
    cid,uids,st=line.rstrip().split('\\t')
    if not uids: continue
    for u in uids.split('|'):
        if u.startswith('ENC'):
            # unique format sample
            base=u.split('_')[0] if '_' in u else u
            cnt[base]+=1
            if len(examples[base])<5: examples[base].append((cid,u))
print('unique enc bases',len(cnt),'total',sum(cnt.values()))
for base,n in list(cnt.items())[:20]: print(base,n,examples[base][:2])
PY"

